"use strict";(self.webpackChunkcolemanlindberg=self.webpackChunkcolemanlindberg||[]).push([[726],{7593:(n,e,t)=>{t.r(e),t.d(e,{default:()=>B});const o=t.p+"static/media/01fourinchesaway.0867b31b9a656414456f.mp3",a=t.p+"static/media/02happynow.fe3d40700a795b9cff03.mp3",i=t.p+"static/media/03math.23c0d803fd3764f32fdf.mp3",s=t.p+"static/media/04slownewsday.1a1899a4eb384feb9dcc.mp3",r=t.p+"static/media/05worthy.7c8a7a1b8db7026d6e0f.mp3",l=t.p+"static/media/06whereiam.8db11dea0dbcf58c6129.mp3",h=t.p+"static/media/07thislovesong.f564735ee5d161301a80.mp3",d=t.p+"static/media/08fiftyyellowtulips.35d1a49fe44a8ad6b6ca.mp3",y=t.p+"static/media/09fourweeks.b805fd603e9ddd08c608.mp3",u=t.p+"static/media/10idareyou.6c7489b5c3dfb83d3803.mp3",m=t.p+"static/media/11pieceofsky.2b389e29f0af4a55e0b5.mp3",g=t.p+"static/media/12boyslive.5b4c69aca6401fc31558.mp3",c=t.p+"static/media/boys_cover.d1be47cbe64e952da574.jpg",w=t.p+"static/media/little-cole_gray2.67819d213d764653cd35.jpeg",I=[{track:"4 Inches Away",lyrics:"I sat out on the grass\nWith a boy that I just met\nWe stared up at the stars\nTil only two were left\nAnd I just there trying to think of\nFunny stuff to say\nKnowing all the time your hand was\nFour inches away\n\nCus I\u2019ve been waiting in the wings\nContemplating risking everything\nI might consider letting my guard down\nIf people stuck around\n\nWe think we\u2019re rivers\nWe run from where we\u2019ve been\nTil one day we dry up\nAnd fall to earth again\nStaying or leaving\nOr just tell me which is worse\nWhen you\u2019re hungry for the open road\nOr when you\u2019re dying of thirst\n\nCus I\u2019ve been waiting in the wings\nI\u2019m contemplating risking everything\nYou know, I might\u2019ve let my guard down\nIf you\u2019d\u2019ve stuck around\n\nI want you here, I want me there\nA molecule is mostly air\nI push on you, you push on me\nA touch is just opposing energy\n\nSo how\u2019s the weather on the East Coast now\nRemember not to let those rich kids\nGet you down\nYou know where to find me if you\u2019re passing through\nMy bed\u2019s not big but\nI\u2019ll make room for you\n\nI sat out on the grass\nWith a boy that I just met\nWe stared up at the stars\nTil only two were left\nAnd I just there trying to think of\nFunny shit to say\nKnowing all the time your hand was\nFour inches away\nThree inches away\nTwo inches away\nA thousand miles away\nTen thousand miles away"},{track:"Happy Now",lyrics:"Another day\nSpent the exact same way\nAnother year\nAnd I\u2019m still here\nThe city tries to grind\nBut we sit around and whine\nThe Seattle of the Midwest\nWith a big Manhattan complex\nSo I am walking downtown\nMy feet make contact with the ground\nThe ground is wet with rain\nAspiring to be snow someday\nAnd all the buildings here are tall\nThey keep the people feeling small\nKeep \u2018em busy pushing papers\nAnd saving all the joy later\n\nI am living on my own\nAnd I am picking at the bones\nOf a society that\nFeeds me mediocrity\nAnd I\u2019ve got bills to pay\nThat\u2019s why I\u2019m working everyday\nThe more I work, the more I\u2019m tired\nAnd I find it hard to be inspired\n\nBut I\u2019ve got wind in my throat\nAnd I\u2019m in love with every note\nAnd these fingers are all mine\nAnd they get me through the hard times\nAnd if I don\u2019t find a way\nTo do what I love everyday\nI know I\u2019m going to die inside\nLike every zombie I see passing by\n\nSo I am walking downtown\nMy feet make contact with the ground\nI cross against the light\nAnd nonchalantly risk my life\nAnd I\u2019ve forgotten where I\u2019m going\nThen I realize it\u2019s snowing\nAnd it\u2019s comforting somehow\nAt least the rain is happy now"},{track:"Math",lyrics:"Add up all our scars\nNights in wretched bars\nAll the books we read\nBrilliant things we\u2019ve said\nAll the time in Rome\nAll the years alone\nNothing can be done\nWe are still only 21\n\nAdd the therapy\nEvery responsibility\nAdd our jaded eyes\nAnd our forehead lines\nEach indignity\nEvery act of mercy\nNothing can be done\nWe are still only 21\n\nAdd up all my sins\nAgainst the love that we were in\nAdd the list of hells\nI have created for myself\nPut them in a box\nNext to my shirts and dirty socks\nSend them back to me\nUnhappily\nAdd where the times we got it right\nWatching the river hold the light\nLaughing through kisses on the street\nConsoling aching feet\nAdd the love we made so new\nAll the long nights we got through\nThe times we weren\u2019t afraid to cry\nNow say goodbye\n\nAdd the movies we have seen\nTo our own suicidal scenes\nAdd our many revelations\nTo our lack of patience\nAdd the all the birds we see outside\nWith such a purpose in their flight\nTo all the chances still to come\nThank god we\u2019re only 21"},{track:"Slow News Day",lyrics:"I don\u2019t give a shit about Monica Lewinski\nI\u2019m just happy that she got laid\nWhile the world was spinning right out of control\nAnd the journalists were calling it a slow news day\n\nWe bombed Baghdad today\nGas prices haven\u2019t been this low in years\nThe economy in my town\u2019s looking up\nWe clench and smile \u201cyou betcha\u201d\n\nI don\u2019t give a shit about Monica Lewinski\nI\u2019m just happy that she got laid\nWhile the world was spinning right out of control\nAnd the journalists were calling it a slow news day\n\nA man and a woman on a corner downtown\nAre dancing cheek to cheek\nOblivious to my stare\nAnd I think it\u2019s great that they found love\nBut there\u2019s a scab on my heart\nThat just got picked open again\n\nCus October in Laramie, Wyoming\nA scarecrow on a deer fence\nBleeding in the cold\nAnd a woman help a sign up at his funeral\nThat said \u201cMatts in hell\u201d and \u201cFags doom nations\u201d\n\nI don\u2019t give a shit about Monica Lewinski\nI\u2019m just happy that she got laid\nWhile the world was spinning right out of control\nAnd the journalists were calling it a slow news day\n\nI walk the streets alone tonight\nThe snow is trying to fly\nIn a bitter cold December sky\nI felt the holes in my pockets\nLike I could piece them back together with my hands\n\nAnd I don\u2019t give a shit about it\nI don\u2019t give a fuck about it\nGive a flying fuck about it\n\nMatts in hell and fags doom nations\nI don\u2019t give a shit about Monica Lewinski"},{track:"Worthy",lyrics:"Today is the day you are born\nRemember the way today feels\nNever forget you\u2019re alive\nNever forget you are loved\nAnd worthy\n\nYou don\u2019t know the months that we\u2019ve waited\nImagining the way you would be\nThe under-the-rib acrobatics you did\nAll the nights your mom spent without sleep\nYou\u2019re unaware of the pain that she felt\nAs you clawed your way into the world\nAll those beautiful noises\nThe gasping for breath\nAs you struggled to make yourself heard\n\nToday is the day you are born\nRemeber the way today feels\nNever forget you\u2019re alive\nNever forget you are loved\nAnd worthy\n\nYou weren\u2019t there when your parents were kids\nMaking love out of all they could find\nPaying bills, making a home\nKeeping the future in mind\nAnd it hard to explain all the ways that they\u2019ve changed\nSince the day that you\u2019ve made yourself known\nAnd the dreams they\u2019ll defer to make room for you now\nCan\u2019t compare to a child of their own\n\nToday is the day you are born\nRemember the way today feels\nNever forget you\u2019re alive\nNever forget you are loved\nAnd worthy\n\nYou can\u2019t conceive of the world you\u2019ve been given\nThat can\u2019t wait to swallow you up\nOr the pains it will take to make sure that you\u2019re safe\nBut you\u2019ll never be quite safe enough\nToday you don\u2019t know what it is to be lonely\nThe fumbling to find who you are\nThe touch of a lover, the ache of a loss\nThey\u2019re just light from a faraway star\n\nToday is the day you are born\nRemeber the way today feels\nNever forget you\u2019re alive\nNever forget you are loved\nAnd worthy"},{track:"Where I End",lyrics:"I could take a bus downtown\nDrink my coffee all alone\nWalk the skyway and never touch the ground\nBut I\u2019d see your face on every bus\nReflected in my coffee cup\nBehind me every time I turn around\n\nAnd I could be wrong\nI could change my mind later on\nBut I don\u2019t know where I end and you begin\nI\u2019m a lost a soul\nAnd I\u2019m weaker than you know\nAnd I don\u2019t know where I end and you begin\n\nI could take a plane to England\nWalk along the streets of London\nDance all night and spend all day in bed\nRemembering how you loved to fly\nHow little details catch your eye\nHow I would rather dance with you instead\n\nAnd I could be wrong\nI could change my mind later on\nBut I don\u2019t know where I end and you begin\nI\u2019m a lost a soul\nAnd I\u2019m weaker than you know\nAnd I don\u2019t know where I end and you begin\n\nSo why don\u2019t you try me\nI can run like hell\nI do whatever it takes to preserve myself\nBut the more that I run\nThe more that I\u2019m lost\nCan you find me\nWill you find me\n\nI could stay inside this room\nNever see the world again\nI could pull the blinds and lock the door\nBut something in the silence\nWould remind me of your voice\nAnd how it spoke to me like nothing had before\nAnd if I choose to leave this world\nAnd live in exile on the moon\nI know I\u2019ll have no light to call my own\nI\u2019ll feel your sunlight warming me\nAnd your stars would keep me company\nYour gravity would keep me looking up\n\nAnd I could be wrong\nI could change my mind later on\nBut I don\u2019t know where I end and you begin\nI\u2019m a lost a soul\nAnd I\u2019m weaker than you know\nAnd I don\u2019t know where I end and you begin"},{track:"This Love Song",lyrics:"You said everything\u2019s been done\nEverything\u2019s been said\nThe songs have all been sung\nAnd all the words are dead\nAnd I said\nI guess I\u2019ll keep my love songs\nTo myself\n\nAnother night\nAnother loud cafe\nI watch your every move\nI hang on every word you say\nYou light a smoke and look around\nAt everything but me\nI wonder what it takes\nTo make you take me seriously\n\nI say people wanna die\nI think we\u2019re hungry for the grave\nWe mass produce our angels\nAnd wonder why we don\u2019t get saved\nBut me, I dream of revolution\nI pray for change\nIt\u2019s all that I know how to do\nAnd I can\u2019t live any other way\n\nYou say \u2018you\u2019re so naive\nI think some time will change your mind\nMe I don\u2019t waste my time in searching\nWhen there\u2019s nothing there to find\nI\u2019ve seen too much corruption\nTo see the world the way you do\nThere\u2019s nothing left to fight for\nAnd I\u2019ve got nothing left to lose\u2019\n\nIt\u2019s 1:15 now\nAnd I ride the last bus home\nWhile the city tried to hide\nBeneath another inch of snow\nI can\u2019t say I blame it\nCus I got dirty places too\nAnd I\u2019d rather be naive\nThan resign myself to suffering with you\n\nYou said everything\u2019s been done\nEverything\u2019s been said\nThe songs have all been sung\nAnd all the words are dead\nAnd I said\nI guess I\u2019ll keep my love songs\nI\u2019ll keep this love song\nTo myself"},{track:"50 Yellow Tulips",lyrics:"On Christmas Eve I brave the rain\nWith my guitar to sing for change\nSo I can buy a present for a friend\nThe thunder loudly criticized\nMy sad attempt at Silent Night\nBut I played until my strings broke\nAnd my fingers bled\n\nAnd the streets are filled with people\nWith somewhere they\u2019d rather be\nLaying their money down\nTossing little scraps to me\nSometimes things are simple\nSometimes it\u2019s enough\nTo buy 50 yellow tulips for someone that you love\n\nI\u2019m far from sane, far from home\nOn crowded streets still alone\nLiving out an open road cliche\nSearching strangers faces\nFor some clue to where my place is\nFinding new diversions everyday\n\nAnd the sidewalk spreads before me\nLike a banquet at my feet\nI calibrate my motions\nTo the rhythm of the street\nI work for what I am\nI work for what I need\nAnd when it\u2019s time to go\nThat\u2019s exactly when I\u2019ll leave\n\nAnd I rarely ever pray\nBut I always seem to sing\nLately I\u2019ve been thinking\nThey\u2019re the same thing\nMy voice can find the beauty in the pain\nThat\u2019s how I know my life is not in vain\nMy voice can find the beauty in the pain\nThat\u2019s how I know my life is not in vain\n\nI got no strings to hold me down\nNo myth to build my world around\nNobody who can make or break my day\nAnd I\u2019m gnawing like a dog\nTo lose this muzzle in my mind\nAnd say exactly what I have to say\n\nSo I take comfor in the worn out chords\nThat have gotten this far\nPress my voice against the air\nAnd every passing car\nSometimes things are simple\nSometimes it\u2019s enough\nTo buy 50 yellow tulips for someone that you love"},{track:"4 Weeks",lyrics:"Four weeks is not a long time\nBut it\u2019s longer than a day\nAnd a day is longer than an hour\nWe can look at it that way\nAnd we can give it all we got\nTil it\u2019s time for us to go\nAnd if things don\u2019t work out\nAt least we\u2019ll know\n\nAnd I really dig you\nI really dig you deep\nAnd that\u2019s not a secret I\nEver tried too hard to keep\nI got no big plans\nI got no strategy\nI just wanna let this thing\nBe what they want to be\n\nPeople say sweet things\nAnd they think that they\u2019re so strong\nThey say forever\nAnd then they\u2019re wrong\nAnd I don\u2019t pretend to know\nAll that much about this life\nBut I know enough to take a chance\nWhen it feels right\n\nAnd I really dig you\nI really dig you deep\nAnd that\u2019s not a secret I\nEver tried too hard to keep\nI got no big plans\nI got no strategy\nI just wanna let this thing\nBe what they want to be\n\nAnd the things is\nYou can have me\nYes I am complex\nBut I\u2019m the real thing\nSo why would you wanna run\nWhy would you wanna hide\nWhy would wanna let a good thing\nPass you by\n\nFour weeks is not a long time\nBut it\u2019s longer than a day\nAnd a day is longer than an hour\nWe can look at it that way\nAnd we can give it all we got\nTil it\u2019s time for us to go\nAnd if things don\u2019t work out\nAt least we\u2019ll know\n\nAnd I really dig you\nI really dig you deep\nAnd that\u2019s not a secret I\nEver tried too hard to keep\nI got no big plans\nI got no strategy\nI just wanna let this thing\nBe what they want to be"},{track:"I Dare You",lyrics:"I got stretch marks\nI got battle scars\nFriends that make me laugh\nAnd a refugee guitar\nI\u2019ve been wind torn\nI\u2019ve been weather worn\nJust killing time until the next storm\nTil the next storm\n\nAnd I\u2019m a sucker for attention\nI can learn to love anyone\nWho can learn to love me\nI\u2019m not saying that I\u2019m desperate\nJust open to the possibilities\n\nAnd I dare you to touch my\nDare you to touch my heart\nI dare you to touch my heart\nAnd keep all your fingers\n\nI\u2019ve been blessed\nWith a beautiful pain\nLoneliness relentless\nAnd as wet as rain\nAnd I\u2019ve never been dry\nAs long as I\u2019ve known\nI came into this world\nAnd I\u2019ll leave it alone\n\nBut I see your broken pieces\nAnd they look like home\nI know your jagged edges\nLike I know my own\nI recognize your demons\nYeah, I got those too\nI could strip out my insides\nAnd show them all to you\n\nAnd I dare you to touch my\nDare you to touch my heart\nI dare you to touch my heart\nAnd keep all your fingers\n\nWhen I was sixteen\nI had blood on my hands\nFrom clawing at walls\nAnd scraping for answers\nAnd now my fingers are rough\nFrom clawing at chords\nAnd searching for songs\nI guess this one must be yours\n\nAnd do I have to put myself to music\nDo I have to make myself so plain\nI can yodel like a cowboy\nI can scream it like a punk\nWith my luck I\u2019m just\nScaring you away\n\nBut it doesn\u2019t hurt to\nDare you to touch my heart\nDare you to touch my heart\nI dare you to touch my heart\nAnd keep all your fingers"},{track:"Piece Of Sky",lyrics:"Is this a love song\nIs this a hit song\nIs this a road song\nIs this a folk song\n\nI don\u2019t concern myself too much\nWith politics these days\nI just do the things I love\nAnd hope the rent gets paid\nI wanna be a virus growing in your ear\nCus when you\u2019re humming this one later\nYou\u2019ll know that I was here\n\nIs this a punk song\nIs this a fight song\nIs this a swan song\nIs this your mom\u2019s song\n\nI don\u2019t concern myself too much\nWith labels anyways\nI just wake each morning blessed\nTo see another day\nI was talking to a friend\nAnd this she told me\nDeath is just as big as being born\nIt is a promise\n\nIs this a love a song\nIs this a hit song\nIs this a road song\nIs this a folk song\n\nHere\u2019s your piece of sky\nWhy don\u2019t you fly"},{track:"Boys (live 1999)",lyrics:"Superman and Wonder Woman\nSaved the world and fell in love\nEvery day of summer \u201883\nWe flew across the tennis court\nMade a deal in my backyard\nYou kissed my cheek and said you\u2019d marry me\n\nBut I got girls for friends now\nAnd you got girlfriends\nAnd you won\u2019t pick me for your kickball team\nAll the rules have changed now\nI guess we\u2019re not engaged now\nAnd I don\u2019t know why you\u2019re so mean to me\nYou boys\n\nWell now I\u2019m 12 and it\u2019s no fun\nInching down the hallway\nAs I\u2019m dodging every insult you can throw\nI hide my body in big sweaters\nGel my hair to style it better\nI\u2019m a freak and everybody knows it\n\nOh but you, you\u2019re so pretty\nYou\u2019re so confident and cool\nAnd I watch you when you\u2019re laughing\nWith your friends\nAnd it\u2019s pathetic\nHow I turn and stare\nEvery time you leave\nOn the off chance that you might come back again\n\nYou boys\nYou love me boys\nYou got me sleeping with the enemy\nYou\u2019re hands have been all over me\nYou boys\nYou love me boys\nYou know I\u2019m waiting waiting\nTo be devastated again\n\nAnd I\u2019m drawn to the one who\nPut me down\nAnd throw me to the ground\nAnd my heartbreak\nAlways breaks my fall\nYou caught my eye\nNow give it back\nCus I\u2019m sick and tired\nOf running into walls\n\nNow it\u2019s cool to be oppressed\nNow I\u2019ve got some street respect\nEverybodys bi or open-minded\nAnd it\u2019s funny how things go around\nThey come around\nYou come around\nAnd say hey, I think I\u2019d like to try that\n\nWell I\u2019m the one who took the blows\nAll those fucking years ago\nAnd now I guess I\u2019ll do some tricks for you\nCus my heart\u2019s already roadkill\nI\u2019ve sold my soul and earned it back\nAnd there\u2019s nothing in the world\nI\u2019d rather do than want you boys\nYou love me boys\nYou got me sleeping with the enemy\nYou\u2019re hands have been all over me\nYou boys\nYou love me boys\nYou know I\u2019m waiting waiting\nTo be devastated again\nCome on baby, devastate me\nYou boys"}],b=t.p+"static/media/boys_curv.9d9058b1f79b1653e080.png",f=Array.isArray(I)&&"string"===typeof I[0]?I.map(n=>JSON.parse(n)):I,p={album:"Boys",cover:c,background:b,color:"#9284f1",colorII:"#9284f1",fontColor:"white",pic:w,about:"In 2000, inspired by the DIY ethics and folk/punk aesthetic of Ani Difranco, I released my first full-length album Boys. I had been writing original songs for about 3 years when I put this record out. It reflected my youth, my struggle to find and keep love, my queer rage, my grief at losing my innocence, and the earnest belief that my friends and I could change the world with music, art, and activism. Boys was a true statement of individuality, emotion, passion, and hope. I may be a more accomplished guitarist and singer now, but I don\u2019t think I\u2019ll ever be as open, raw, and honest as I was on Boys.",tracks:[{name:"4 Inches Away",artist:"Coleman Lindberg",album:"Boys",url:o,id:0,image:c,pic:w,lyrics:f[0].lyrics},{name:"Happy Now",artist:"Coleman Lindberg",album:"Boys",url:a,id:1,image:c,pic:w,lyrics:f[1].lyrics},{name:"Math",artist:"Coleman Lindberg",album:"Boys",url:i,id:2,image:c,pic:w,lyrics:f[2].lyrics},{name:"Slow News Day",artist:"Coleman Lindberg",album:"Boys",url:s,id:3,image:c,pic:w,lyrics:f[3].lyrics},{name:"Worthy",artist:"Coleman Lindberg",album:"Boys",url:r,id:4,image:c,pic:w,lyrics:f[4].lyrics},{name:"Where I End",artist:"Coleman Lindberg",album:"Boys",url:l,id:5,image:c,pic:w,lyrics:f[5].lyrics},{name:"This Love Song",artist:"Coleman Lindberg",album:"Boys",url:h,id:6,image:c,pic:w,lyrics:f[6].lyrics},{name:"50 Yellow Tulips",artist:"Coleman Lindberg",album:"Boys",url:d,id:7,image:c,pic:w,lyrics:f[7].lyrics},{name:"4 Weeks",artist:"Coleman Lindberg",album:"Boys",url:y,id:8,image:c,pic:w,lyrics:f[8].lyrics},{name:"I Dare You",artist:"Coleman Lindberg",album:"Boys",url:u,id:9,image:c,pic:w,lyrics:f[9].lyrics},{name:"Piece Of Sky",artist:"Coleman Lindberg",album:"Boys",url:m,id:10,image:c,pic:w,lyrics:f[10].lyrics},{name:"Boys (live 1999)",artist:"Coleman Lindberg",album:"Boys",url:g,id:11,image:c,pic:w,lyrics:f[11].lyrics}]},k=(f[0].lyrics,f[1].lyrics,f[2].lyrics,f[3].lyrics,f[4].lyrics,f[5].lyrics,f[6].lyrics,f[7].lyrics,f[8].lyrics,f[9].lyrics,f[10].lyrics,f[11].lyrics,p);var v=t(7283),A=t(8540),T=t(5623),W=t(579);function B(){return console.log(k),(0,W.jsx)("div",{style:{display:"flex",alignItems:"center"},children:(0,W.jsx)(v.A,{album:k,background:k.background,AudioPlayer:A.A,AlbumAboutCard:T.A})})}}}]);
